}

memoria.ultimoProcesso[String(de.id)] = alvo.id;

const querRedigir = /redi[jg]|retorno|mensagem|escrev|comunic|avis/i.test(texto);

return { json: { ...base, rota: querRedigir ? 'redigir' : 'consulta',
